"""Independent replay/certificate verifier used only for local development."""
import copy, json, math
from typing import *

def tol(a,b): return 1e-7+1e-7*max(abs(a),abs(b))
def close(a,b): return abs(a-b)<=tol(a,b)
def eq0(a): return abs(a)<=1e-7
def keys_exact(d,ks,where):
    if type(d) is not dict or set(d)!=set(ks):
        raise AssertionError(f'keys {where}: got {set(d) if type(d) is dict else type(d)} expected {set(ks)}')

def num(x,where,lo=None,hi=None,signed=False):
    if type(x) not in (int,float) or type(x) is bool or not math.isfinite(x):
        raise AssertionError(f'not finite number {where}: {x!r}')
    if lo is not None and x < lo-1e-12: raise AssertionError(f'below {where}: {x}')
    if hi is not None and x > hi+1e-12: raise AssertionError(f'above {where}: {x}')
    if not signed and x < 0: raise AssertionError(f'negative {where}: {x}')
    return float(x)

def vec(x,n,where,lo=None,hi=None,signed=False):
    if type(x) is not list or len(x)!=n: raise AssertionError(f'vec shape {where}')
    return [num(v,f'{where}[{i}]',lo,hi,signed) for i,v in enumerate(x)]

def mat(x,rs,cs,where,lo=None,hi=None,signed=False):
    if type(x) is not list or len(x)!=len(rs): raise AssertionError(f'mat rows {where}')
    return [vec(row,cs[i],f'{where}[{i}]',lo,hi,signed) for i,row in enumerate(x)]

def verify_worker(caps,demands,paths,owned,mode,rho,B,res):
    E=len(caps); admit=(mode=='admit')
    keys_exact(res, {'status','flow','edge_load','potential'} if res.get('status')=='optimal' else {'status','unroutable'}, 'worker result')
    if res['status']=='infeasible':
        assert mode=='route', 'infeasible in admit'
        unr=[int(k) for k in res['unroutable']]
        if unr!=sorted(unr): raise AssertionError('unroutable not sorted')
        exp=sorted(k for k in owned if demands[k]>0 and not any(p is not None and all(caps[e]>0 for e in p) for p in paths[k]))
        if unr!=exp: raise AssertionError(f'unroutable mismatch {unr} {exp}')
        return
    assert res['status']=='optimal','bad status'
    flow=mat(res['flow'],owned,[len(paths[k]) for k in owned],'flow',0,1e9)
    load=vec(res['edge_load'],E,'edge_load',0,1e9)
    lam=vec(res['potential'],len(owned),'potential',-1e9,1e9,signed=True)
    if admit:
        for i,v in enumerate(lam):
            if v < -1e-9: raise AssertionError('negative admit potential')
    # fixed zeros and nonneg/load recompute
    for oi,k in enumerate(owned):
        for p,path in enumerate(paths[k]):
            x=flow[oi][p]
            avail=path is not None and all(caps[e]>0 for e in path)
            if demands[k]==0 or not avail:
                if x!=0: raise AssertionError(f'fixed flow nonzero k{k} p{p} x{x}')
    rec=[0.0]*E
    for oi,k in enumerate(owned):
        for p,path in enumerate(paths[k]):
            if path is None: continue
            x=flow[oi][p]
            for e in path: rec[e]+=x
    for e in range(E):
        if caps[e]<=0:
            if load[e]!=0: raise AssertionError(f'withdrawn load nonzero e{e}')
        if not close(rec[e],load[e]): raise AssertionError(f'load recompute e{e} {rec[e]} {load[e]}')
    # objective
    f=0.0
    for oi,k in enumerate(owned):
        for x in flow[oi]: f += 0.5*x*x
    for e in range(E):
        if caps[e]>0:
            f += 0.5*rho*(load[e]/caps[e]-B[e])**2
    R=sum(sum(row) for row in flow)
    f -= R if admit else 0.0
    # sums and gradients
    G={}
    for oi,k in enumerate(owned):
        sm=sum(flow[oi])
        if mode=='route':
            if not close(sm,demands[k]): raise AssertionError(f'route sum k{k} {sm} {demands[k]}')
        else:
            if sm>demands[k]+tol(sm,demands[k]): raise AssertionError(f'admit sum k{k} {sm} {demands[k]}')
        for p,path in enumerate(paths[k]):
            if path is None: continue
            if demands[k]<=0 or not all(caps[e]>0 for e in path): continue
            g=flow[oi][p]-(1.0 if admit else 0.0)
            for e in path:
                g += rho*(load[e]/caps[e]-B[e])/caps[e]
            G[(oi,p)]=g
            if g+lam[oi] < -tol(g+lam[oi],0):
                # use a tolerance including the magnitudes involved
                lim=1e-7+1e-7*max(abs(g),abs(lam[oi]),abs(g+lam[oi]))
                if g+lam[oi] < -lim:
                    raise AssertionError(f'reduced cost negative k{k} p{p}: {g+lam[oi]}')
    if admit:
        for oi,k in enumerate(owned):
            if lam[oi] < -1e-9: raise AssertionError('negative potential')
    D=f
    for oi,k in enumerate(owned):
        for p in range(len(paths[k])):
            if (oi,p) in G: D -= flow[oi][p]*G[(oi,p)]
        D -= demands[k]*lam[oi]
        if demands[k]==0 and lam[oi]!=0: raise AssertionError('zero demand potential nonzero')
    if not close(D,f): raise AssertionError(f'f/D mismatch f={f} D={D} diff={D-f} tol={tol(D,f)}')

def verify_case(case,out):
    keys_exact(out,{'events'},'case output')
    events=out['events']
    if type(events) is not list or len(events)!=len(case['events']): raise AssertionError('events count')
    W=len(case['workers']);E=len(case['edges']);K=len(case['commodities'])
    alpha=case['relax'][0]/case['relax'][1]
    c=[e[2] for e in case['edges']]
    d=[k['demand'] for k in case['commodities']]
    paths=[[None if p is None else list(p) for p in k['paths']] for k in case['commodities']]
    mode=case['mode'];rho=case['rho'];gen=0;r=0
    z=[0.0]*E;u=[0.0]*E
    flows=[[0.0]*len(paths[k]) for k in range(K)]
    A=[[0.0]*E for _ in range(W)]
    seen=set();fresh=set();last=[None]*W;latest=[None]*W
    issued={}; received=set();seq_counter=0;checkpoints={}
    maxlag=case['max_lag'];quorum=case['quorum']
    def summary():
        S=[0.0]*E
        for ww in range(W):
            for e in range(E): S[e]+=A[ww][e]
        X=[S[e]/c[e] if c[e]>0 else 0.0 for e in range(E)]
        return S,X
    for idx,(ev,res) in enumerate(zip(case['events'],events)):
        op=ev['op']
        if op=='configure':
            keys_exact(res,{'op','generation'},f'configure{idx}')
            assert res['op']=='configure'
            # patch
            for e,cap in ev['capacity']: c[e]=cap
            for k,dem in ev['demand']: d[k]=dem
            for k,p,path in ev['paths']: paths[k][p]=None if path is None else list(path)
            mode=ev['mode'];gen+=1
            if type(res['generation']) is not int or res['generation']!=gen: raise AssertionError(f'configure gen {res["generation"]} {gen}')
            r=0;z=[0.0]*E;u=[0.0]*E
            flows=[[0.0]*len(paths[k]) for k in range(K)]
            A=[[0.0]*E for _ in range(W)]
            seen=set();fresh=set();last=[None]*W;latest=[None]*W
        elif op=='issue':
            keys_exact(res,{'op','id','worker','generation','bias','rho','result'},f'issue{idx}')
            assert res['op']=='issue' and res['id']==ev['id'] and res['worker']==ev['worker']
            if type(res['generation']) is not int or res['generation']!=gen: raise AssertionError('issue gen')
            if type(res['rho']) is not int or res['rho']!=rho: raise AssertionError('issue rho')
            S,X=summary(); w=ev['worker']
            B=[]
            for e in range(E):
                B.append(0.0 if c[e]<=0 else A[w][e]/c[e]+(z[e]-X[e]-u[e])/W)
            got=vec(res['bias'],E,'bias',-1e9,1e9,signed=True)
            for e in range(E):
                if not close(got[e],B[e]): raise AssertionError(f'bias mismatch e{e} got{got[e]} exp{B[e]}')
            # use independently computed B for certificate (same as response within tol)
            verify_worker(c,d,paths,case['workers'][w],mode,float(rho),B,res['result'])
            issued[ev['id']]={'worker':w,'generation':gen,'seq':seq_counter,'rho':rho,
                              'proposal':copy.deepcopy(res['result']),'owned':list(case['workers'][w])}
            seq_counter+=1
        elif op=='deliver':
            keys_exact(res,{'op','id','status'},f'deliver{idx}')
            assert res['op']=='deliver' and res['id']==ev['id']
            tid=ev['id']
            if tid in received: exp='duplicate'
            else:
                t=issued[tid];w=t['worker']
                if t['generation']!=gen: exp='obsolete'
                elif latest[w] is not None and t['seq']<latest[w]: exp='superseded'
                elif t['proposal']['status']=='infeasible': exp='infeasible'
                else: exp='accepted'
            if res['status']!=exp: raise AssertionError(f'deliver status got {res["status"]} exp {exp}')
            if tid not in received:
                received.add(tid)
                if exp=='accepted':
                    t=issued[tid];w=t['worker']
                    for oi,k in enumerate(t['owned']):
                        flows[k]=[float(x) for x in t['proposal']['flow'][oi]]
                    A[w]=[float(x) for x in t['proposal']['edge_load']]
                    latest[w]=t['seq'];seen.add(w);fresh.add(w);last[w]=r
        elif op=='step':
            missing=[w for w in range(W) if w not in seen]
            stale=[w for w in sorted(seen) if r-last[w]>maxlag]
            fr=sorted(fresh)
            if missing or stale or len(fr)<quorum:
                keys_exact(res,{'op','status','missing','stale','fresh'},f'stepwait{idx}')
                if res['op']!='step' or res['status']!='waiting': raise AssertionError('expected waiting')
                if res['missing']!=missing or res['stale']!=stale or res['fresh']!=fr: raise AssertionError(f'waiting sets got {res} exp {missing,stale,fr}')
            else:
                keys_exact(res,{'op','status','round','load','ceiling','z','dual','pressure'},f'stepadv{idx}')
                if res['op']!='step' or res['status']!='advanced': raise AssertionError('expected advanced')
                if type(res['round']) is not int or res['round']!=r+1: raise AssertionError('round')
                S,X=summary(); gotload=vec(res['load'],E,'adv load',0,1e9)
                for e in range(E):
                    if not close(gotload[e],S[e]): raise AssertionError(f'adv load {e}')
                z0=list(z);u0=list(u)
                ce=float(res['ceiling']); gotz=vec(res['z'],E,'adv z',-1e9,1e9,signed=True)
                gott=vec(res['pressure'],E,'adv pressure',0,1e9)
                gotu=vec(res['dual'],E,'adv dual',-1e9,1e9,signed=True)
                live=[e for e in range(E) if c[e]>0]
                V={e:alpha*X[e]+(1-alpha)*z0[e]+u0[e] for e in live}
                if not live:
                    if mode=='route': assert abs(ce)<=1e-7
                    else: assert abs(ce-1)<=1e-7
                for e in range(E):
                    if c[e]<=0:
                        if gotz[e]!=0 or gotu[e]!=0 or gott[e]!=0: raise AssertionError(f'withdrawn controller nonzero e{e}')
                    else:
                        if mode=='route':
                            if ce < -1e-9: raise AssertionError('route h negative')
                            if gotz[e] > ce + 1e-7*max(1,abs(ce),abs(gotz[e])): raise AssertionError('z>h')
                        else:
                            if abs(ce-1)>1e-7: raise AssertionError('admit h')
                            if gotz[e] > 1.0 + 1e-7: raise AssertionError('admit z>h')
                        st=rho*(gotz[e]-V[e])+gott[e]
                        if not eq0(st): raise AssertionError(f'pressure stationarity e{e} {st}')
                        comp=gott[e]*(ce-gotz[e])
                        if not eq0(comp): raise AssertionError(f'pressure comp e{e} {comp}')
                        eu=u0[e]+alpha*X[e]+(1-alpha)*z0[e]-gotz[e]
                        if not close(gotu[e],eu): raise AssertionError(f'dual identity e{e} {gotu[e]} {eu}')
                if mode=='route':
                    ss=sum(gott[e] for e in live)
                    if ss > 1.0 + 1e-7: raise AssertionError(f'route sum pressure {ss}')
                    if not eq0(ce*(1.0-ss)): raise AssertionError(f'route h complementarity {ce*(1-ss)}')
                z=gotz;u=gotu;r+=1;fresh=set()
        elif op=='retune':
            keys_exact(res,{'op','rho'},f'retune{idx}')
            assert res['op']=='retune' and type(res['rho']) is int and res['rho']==ev['rho']
            old=rho;new=ev['rho']
            if new!=old: u=[x*old/new for x in u]
            rho=new
        elif op=='save':
            keys_exact(res,{'op','name'},f'save{idx}')
            assert res['op']=='save' and type(res['name']) is int and res['name']==ev['name']
            checkpoints[ev['name']]={'c':list(c),'d':list(d),'paths':copy.deepcopy(paths),'mode':mode,'rho':rho,
                'r':r,'z':list(z),'u':list(u),'flows':copy.deepcopy(flows),'A':copy.deepcopy(A),
                'seen':set(seen),'fresh':set(fresh),'last':list(last),'latest':list(latest)}
        elif op=='restore':
            keys_exact(res,{'op','name','generation'},f'restore{idx}')
            assert res['op']=='restore' and type(res['name']) is int and res['name']==ev['name']
            gen+=1
            if type(res['generation']) is not int or res['generation']!=gen: raise AssertionError('restore gen')
            s=checkpoints[ev['name']]
            c=list(s['c']);d=list(s['d']);paths=copy.deepcopy(s['paths']);mode=s['mode'];rho=s['rho']
            r=s['r'];z=list(s['z']);u=list(s['u']);flows=copy.deepcopy(s['flows']);A=copy.deepcopy(s['A'])
            seen=set(s['seen']);fresh=set(s['fresh']);last=list(s['last']);latest=list(s['latest'])
        elif op=='audit':
            keys_exact(res,{'op','generation','round','rho','flow','worker_load','load','z','dual','seen','fresh','age'},f'audit{idx}')
            assert res['op']=='audit'
            if type(res['generation']) is not int or res['generation']!=gen: raise AssertionError('audit gen')
            if type(res['round']) is not int or res['round']!=r: raise AssertionError('audit r')
            if type(res['rho']) is not int or res['rho']!=rho: raise AssertionError('audit rho')
            gf=mat(res['flow'],list(range(K)),[len(paths[k]) for k in range(K)],'audit flow',0,1e9)
            for k in range(K):
                for p,x in enumerate(gf[k]):
                    if not close(x,flows[k][p]): raise AssertionError(f'audit flow k{k}p{p}: {x} {flows[k][p]}')
            gA=mat(res['worker_load'],range(W),[E]*W,'audit worker_load',0,1e9)
            for w in range(W):
                for e in range(E):
                    if not close(gA[w][e],A[w][e]): raise AssertionError(f'audit A {w}{e}')
            S,X=summary();gl=vec(res['load'],E,'audit load',0,1e9)
            for e in range(E):
                if not close(gl[e],S[e]): raise AssertionError(f'audit load {e}')
            gz=vec(res['z'],E,'audit z',-1e9,1e9,signed=True);gu=vec(res['dual'],E,'audit dual',-1e9,1e9,signed=True)
            for e in range(E):
                if not close(gz[e],z[e]) or not close(gu[e],u[e]): raise AssertionError(f'audit z/u {e}')
            exp_seen=sorted(seen);exp_fresh=sorted(fresh)
            if type(res['seen']) is not list or res['seen']!=exp_seen: raise AssertionError('audit seen')
            if type(res['fresh']) is not list or res['fresh']!=exp_fresh: raise AssertionError('audit fresh')
            if type(res['age']) is not list or len(res['age'])!=W: raise AssertionError('audit age shape')
            for w in range(W):
                exp=None if w not in seen else r-last[w]
                if res['age'][w]!=exp: raise AssertionError(f'audit age w{w} got {res["age"][w]} exp {exp}')
        else:
            raise AssertionError('unknown op verifier')

def verify_request(req,out):
    keys_exact(out,{'cases'},'root output')
    if type(out['cases']) is not list or len(out['cases'])!=len(req['cases']): raise AssertionError('cases count')
    for case,cout in zip(req['cases'],out['cases']): verify_case(case,cout)
